/// Called when shadow root is popped from the element.
///
/// **Experimental.**
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct ShadowRootPoppedEvent {
    /// Host element id.
    #[serde(rename = "hostId")]
    pub host_id: NodeId,
    /// Shadow root id.
    #[serde(rename = "rootId")]
    pub root_id: NodeId,
}

impl crate::Event for ShadowRootPoppedEvent {
    const NAME: &'static str = "DOM.shadowRootPopped";
}

/// Payload of the `DOM.shadowRootPushed` event.
///
/// Called when shadow root is pushed into the element.
///
/// **Experimental.**
#[derive(Debug, Clone, PartialEq, Default, Serialize, Deserialize)]
pub struct ShadowRootPushedEvent {
    /// Host element id.
    #[serde(rename = "hostId")]
    pub host_id: NodeId,
    /// Shadow root.
    #[serde(rename = "root")]
    pub root: Node,
}

impl crate::Event for ShadowRootPushedEvent {
    const NAME: &'static str = "DOM.shadowRootPushed";
}

